// calculator.ts
// Core calculation utilities for the incentive calculator.

import { TaxParams, computeStateTax, defaultTaxParams } from './params';

export type TaxModel = 'flat' | 'finland' | 'custom';

export interface UserParams {
  hourlyWage: number; // €/h
  hoursPerMonth: number; // h
  taxRate?: number; // 0-1, used if taxModel === 'flat' or as a fallback
  taxModel?: TaxModel;
  taxParams?: TaxParams; // optional parameters for 'finland' or 'custom'
}

function clamp01(v: number) {
  if (Number.isNaN(v) || !isFinite(v)) return 0;
  return Math.max(0, Math.min(1, v));
}

// computeTaxRateForMonthlyIncome computes an overall tax rate (0-1) for a given
// gross monthly income. When taxModel='finland' it uses progressive state tax,
// municipal tax and social security contributions to compute an effective rate.
export function computeTaxRateForMonthlyIncome(
  grossMonthlyIncome: number,
  model: TaxModel = 'flat',
  params = defaultTaxParams,
  flatFallbackRate = 0.25
): number {
  if (model === 'flat') return clamp01(flatFallbackRate);

  // Finland model: annualize income, compute state tax, add municipal/church/social
  const annualIncome = grossMonthlyIncome * 12;
  const stateTax = computeStateTax(annualIncome, params.stateTaxBrackets);
  // stateTax / annualIncome -> fraction of income paid as state tax
  const stateTaxFraction = annualIncome > 0 ? stateTax / annualIncome : 0;
  const taxPercent = params.municipalTaxRate + params.churchTaxRate + stateTaxFraction + params.socialSecurityRate;
  return clamp01(taxPercent);
}

// Additional helper: compute gross income from user params
export function grossIncome(user: UserParams) {
  return user.hourlyWage * user.hoursPerMonth;
}

export default {
  computeTaxRateForMonthlyIncome,
  grossIncome
};
