// ui/results.ts
// Simple results renderer for the demo UI.

export function renderResults(root: HTMLElement, data: { gross: number; taxRate: number; net: number }) {
  root.innerHTML = `
    <div>
      <div><strong>Gross monthly income:</strong> €${data.gross.toFixed(2)}</div>
      <div><strong>Effective tax rate (vero %):</strong> ${(data.taxRate * 100).toFixed(2)}%</div>
      <div><strong>Net monthly income:</strong> €${data.net.toFixed(2)}</div>
    </div>
  `;
}
