// params.ts
// Configuration and parameters for tax models (English variable names, Finnish terms in comments)

export interface StateTaxBracket {
  // threshold in euros (annual). The rate applies to income above this threshold up to next bracket.
  threshold: number;
  // marginal rate for the bracket (0-1)
  rate: number;
}

export interface TaxParams {
  municipalTaxRate: number; // e.g. 0.19 (kuntavero)
  churchTaxRate: number; // optional church tax (kirkollisvero)
  socialSecurityRate: number; // e.g. 0.07 (sosiaaliturvamaksu)
  stateTaxBrackets: StateTaxBracket[]; // progressive state tax (valtionvero)
}

// Default example parameters for Finland (illustrative). Keep brackets in ascending order.
export const defaultTaxParams: TaxParams = {
  municipalTaxRate: 0.19,
  churchTaxRate: 0.0,
  socialSecurityRate: 0.07,
  stateTaxBrackets: [
    { threshold: 0, rate: 0.0 },
    { threshold: 14700, rate: 0.06 },
    { threshold: 24000, rate: 0.17 },
    { threshold: 44000, rate: 0.21 },
    { threshold: 78000, rate: 0.31 },
    { threshold: 150000, rate: 0.35 }
  ]
};

// computeStateTax calculates annual state tax (valtionvero) using progressive brackets.
// It treats each bracket.rate as the marginal rate applied to the portion of income
// above bracket.threshold up to the next bracket.threshold.
export function computeStateTax(annualIncome: number, brackets: StateTaxBracket[]): number {
  if (annualIncome <= 0) return 0;
  const sorted = brackets.slice().sort((a, b) => a.threshold - b.threshold);
  let tax = 0;
  for (let i = 0; i < sorted.length; i++) {
    const current = sorted[i];
    const next = sorted[i + 1];
    const lower = current.threshold;
    const upper = next ? next.threshold : Infinity;
    if (annualIncome <= lower) break;
    const taxable = Math.min(annualIncome, upper) - lower;
    if (taxable > 0) {
      tax += taxable * current.rate;
    }
    if (annualIncome <= upper) break;
  }
  return Math.max(0, tax);
}

export default defaultTaxParams;
